sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    try {

        if (current.response_code_for_detail == "200" && current.response_code_for_summary == "200") {
            var responsebody = current.response_body_for_detail.toString();
            var respBody = JSON.parse(responsebody);
            var responsebodySum = current.response_body_for_summary.toString();
            var respBodySum = JSON.parse(responsebodySum);
            for (var i = 0; i < respBody.data.length; i++) {
                for (var j = 0; j < respBody.data[i].holdings.length; j++) {
                    var positionDetail = new GlideRecord("x_hsb11_mss_pos_custody_positions_details");
                    positionDetail.initialize();
                    positionDetail.holding_event_type = respBody.data[i].holdings[j].type;
                    positionDetail.security_account = respBody.data[i].safekeepingAccountIdentification;
                    positionDetail.security_id = respBody.data[i].financialInstrumentIdentification.hsbcIdentifier;
                    positionDetail.currency = respBody.data[i].financialInstrumentIdentification.currency;
                    positionDetail.quantity_available = respBody.data[i].holdings[j].quantity;
                    positionDetail.registration_code = respBody.data[i].holdings[j].registrationCode;
                    positionDetail.location_id = respBody.data[i].holdings[j].locationCode;
                    positionDetail.available_balance = respBodySum.data[i].balances.available.quantity;
                    positionDetail.traded_balance = respBodySum.data[i].balances.traded.quantity;
                    positionDetail.settled_balance = respBodySum.data[i].balances.settled.quantity;
                    positionDetail.account_name = respBody.data[i].safekeepingAccountName;
                    positionDetail.security_name = respBody.data[i].financialInstrumentIdentification.description;
                    positionDetail.trade_id = current.trade_reference;
                    positionDetail.trade_base = current.trade_reference; //Custody Redesign
                    positionDetail.market_value_in_security_curr = respBody.data[i].holdings[j].marketValueInSecurityCurrency;
                    positionDetail.market_value_in_report_value = respBody.data[i].holdings[j].marketValueInReportCurrency;
                    positionDetail.type = current.type;
                    positionDetail.triggered_by = current.triggered_by;
                    positionDetail.insert();
                }
            }
        }
        if (current.type == 'trade') {
            var tradeData = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
            tradeData.addQuery("sys_id", current.trade_reference);
            tradeData.query();
            if (tradeData.next()) {
                if (current.response_code_for_detail == "200" && current.response_code_for_summary == "200") {
                    tradeData.position_attribute_sync = "Response Success-All fields updated(200)";
                    tradeData.last_positions_refresh_date_time = new GlideDateTime();

                    if (current.task_reference != "") {
                        var taskData = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_task");
                        taskData.get(current.task_reference);
                        taskData.position_attribute_sync = "Response Success-All fields updated(200)";
                        taskData.update();
                    }

                } else if (current.response_code_for_detail.toString.startsWith('4')) {
                    tradeData.position_attribute_sync = "Response Un-Successful-400 Error";
                    tradeData.last_positions_refresh_date_time = new GlideDateTime();

                } else if (current.response_body_for_detail.toString().startsWith('5')) {
                    tradeData.position_attribute_sync = "Response Un-Successful-500 Error";
                    tradeData.last_positions_refresh_date_time = new GlideDateTime();

                } else {
                    taskData.position_attribute_sync = "Response Un-Successful - Error";
                    tradeData.last_positions_refresh_date_time = new GlideDateTime();

                    if (current.task_reference != "") {
                        var taskDataErr = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_task");
                        taskDataErr.get(current.task_reference);
                        taskDataErr.position_attribute_sync = "Response Un-Successful - Error";
                        taskDataErr.update();
                    }
                    tradeData.update();
                }
            }
        }
    } catch (e) {
        gs.info("unexpected error occured" + e);
    }

})(current, previous);
